    apiKey: async () => voiceCredential(currentVoiceModel(this.voiceModelId()), (provider) => this.providerKey(provider)),
    missingKeyMessage: () => missingKeyMessage(currentVoiceModel(this.voiceModelId())),
    onStatus: (status) => {
