test('a local model downloads when picked (no network) and becomes the voice model when it is ready', async () => {
  const { win, userData } = await start('models-local');
  await setKey(win, 'deepgram', 'valid-deepgram');
  await win.reload();
  await win.waitForSelector('.dock');
  await openSettings(win);

  // Nothing is on this PC yet: the row offers the download.
  const parakeet = voiceList(win).getByRole('radio', { name: /^Parakeet,/ });
  await expect(voiceList(win).getByRole('button', { name: 'Download Parakeet', exact: true })).toBeVisible();
  await parakeet.click();

  // Under --e2e the download is answered by a stub inside the app: the real lifecycle runs
  // (downloading, unpacking, ready) and the choice follows it.
  await expect(parakeet).toHaveAttribute('aria-checked', 'true', { timeout: 20 * SECOND });
  await expect(voiceList(win).getByRole('button', { name: 'Delete Parakeet' })).toBeVisible();
  expect((await currentSettings(win)).voiceModelId).toBe('parakeet:v2');
  const states = await win.evaluate(() => (window as unknown as { usefulVoice: { parakeetStates(): Promise<Record<string, { status: string; sizeBytes?: number }>> } }).usefulVoice.parakeetStates());
  // Four one-byte files from the stub: the real 480 MB archive was never fetched.
  expect(states.v2).toMatchObject({ status: 'ready', sizeBytes: 4 });
  const requests = await fs.readFile(path.join(userData, 'e2e.log'), 'utf8');
  expect(requests).toMatch(/parakeet GET https:\/\/github\.com\//);
  // Every request the app made for the model went to the in-app stub, and no other host was asked.
  expect(requests.split('\n').filter((line) => / parakeet GET /.test(line)).length).toBe(1);

  // A failed download offers a retry, and does not switch anything.
  const multilingual = voiceList(win).getByRole('radio', { name: /^Parakeet Multilingual,/ });
  await sendToMain(run!.app, 'parakeet:changed', { v2: states.v2, v3: { status: 'failed', message: 'offline' } });
  await expect(voiceList(win).getByRole('button', { name: 'Retry Parakeet Multilingual' })).toBeVisible();
  await expect(multilingual).toHaveAttribute('aria-checked', 'false');
  expect((await currentSettings(win)).voiceModelId).toBe('parakeet:v2');
});

